	}
	if err := json.Unmarshal(recorder.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if body.Version.RollbackOf == nil || *body.Version.RollbackOf != 1 {
		t.Fatalf("rollbackOf = %v, want 1", body.Version.RollbackOf)
